import { item } from '../../../../schema/item/index.js';
import { fromSchemaDTO } from './attribute.js';
/**
 * @debt feature "handle defaults, links & validators"
 */
export const fromItemSchemaDTO = ({ keyDefault, putDefault, updateDefault, keyLink, putLink, updateLink, attributes }) => {
    keyDefault;
    putDefault;
    updateDefault;
    keyLink;
    putLink;
    updateLink;
    return item(Object.fromEntries(Object.entries(attributes).map(([attributeName, attribute]) => [
        attributeName,
        fromSchemaDTO(attribute)
    ])));
};
